#[test]
fn enrolment_request_challenge_and_proof_round_trip_through_the_v1_wire_contract() {
    let request = EnrollmentRequest {
        request_id: "request-a".into(),
        tenant_id: "tenant-a".into(),
        repository_id: "repository-a".into(),
        proposed_node_id: "node-a".into(),
        display_name: "Build node A".into(),
        public_key_fingerprint: "ed25519:7f3a".into(),
        requested_capabilities: vec!["synchronize.v1".into()],
        created_at: "2026-08-11T00:00:00Z".into(),
        expires_at: "2026-08-11T00:10:00Z".into(),
        public_key: vec![7; 32],
    };
    let challenge_request = EnrollmentChallengeRequest {
        request_id: request.request_id.clone(),
        tenant_id: request.tenant_id.clone(),
        repository_id: request.repository_id.clone(),
        proposed_node_id: request.proposed_node_id.clone(),
        public_key_fingerprint: request.public_key_fingerprint.clone(),
    };
    let challenge = EnrollmentChallenge {
        request_id: challenge_request.request_id.clone(),
        tenant_id: challenge_request.tenant_id.clone(),
        repository_id: challenge_request.repository_id.clone(),
        proposed_node_id: challenge_request.proposed_node_id.clone(),
        public_key_fingerprint: challenge_request.public_key_fingerprint.clone(),
        nonce: vec![1; 32],
        issued_at: "2026-08-11T00:01:00Z".into(),
        expires_at: "2026-08-11T00:02:00Z".into(),
        state: EnrollmentState::Approved as i32,
    };
    let proof = EnrollmentActivationProof {
        request_id: challenge.request_id.clone(),
        tenant_id: challenge.tenant_id.clone(),
        repository_id: challenge.repository_id.clone(),
        proposed_node_id: challenge.proposed_node_id.clone(),
        public_key_fingerprint: challenge.public_key_fingerprint.clone(),
        nonce: challenge.nonce.clone(),
        signature: vec![2; 64],
    };

    assert_eq!(
        (
            EnrollmentRequest::decode(request.encode_to_vec().as_slice()).unwrap(),
            EnrollmentChallengeRequest::decode(challenge_request.encode_to_vec().as_slice())
                .unwrap(),
            EnrollmentChallenge::decode(challenge.encode_to_vec().as_slice()).unwrap(),
            EnrollmentActivationProof::decode(proof.encode_to_vec().as_slice()).unwrap(),
        ),
        (request, challenge_request, challenge, proof)
    );
}

/// ADR-0085 decision 5 requires Ackplane to verify the activation signature,
/// which is impossible from a fingerprint: a fingerprint is a hash of a key,
/// not a key. The contract shipped carrying only the fingerprint, so every
/// signature in the system was unverifiable. Fixed by carrying the key itself
/// on the enrolment request, which is the message ADR-0085 decision 2 names.
#[test]
fn an_enrolment_request_carries_the_verifying_key_and_not_merely_its_fingerprint() {
    let key = vec![7; 32];
    let request = EnrollmentRequest {
        request_id: "request-a".into(),
        tenant_id: "tenant-a".into(),
        repository_id: "repository-a".into(),
        proposed_node_id: "node-a".into(),
        display_name: "Build node A".into(),
        public_key_fingerprint: "ed25519:7f3a".into(),
        requested_capabilities: vec!["synchronize.v1".into()],
        created_at: "2026-08-11T00:00:00Z".into(),
        expires_at: "2026-08-11T00:10:00Z".into(),
        public_key: key.clone(),
    };

    let decoded = EnrollmentRequest::decode(request.encode_to_vec().as_slice()).unwrap();

    assert_eq!(decoded.public_key, key);
    assert_ne!(
        decoded.public_key.as_slice(),
        decoded.public_key_fingerprint.as_bytes(),
        "the key must travel in its own field, not be aliased to the fingerprint"
    );

    // A different key under an identical fingerprint must reach the wire as a
    // different request; otherwise the field is declared but never transmitted.
    let impostor = EnrollmentRequest {
        public_key: vec![8; 32],
        ..request.clone()
    };

    assert_ne!(impostor.encode_to_vec(), request.encode_to_vec());
}

/// The key travels once, at enrolment. Approval binds to the fingerprint
/// (ADR-0085 decision 4), so a proof able to carry its own key could present a
/// different one after approval and be verified against it, making the approval
/// meaningless. Field 10 must therefore stay unassigned on the proof: splice one
/// onto the wire and it has to be discarded, not absorbed. This fails if anyone
/// later adds a key field to the proof, which is the point — the absence is a
/// security property, not an oversight.
#[test]
fn an_activation_proof_cannot_smuggle_a_key_past_the_approved_fingerprint() {
    let proof = EnrollmentActivationProof {
        request_id: "request-a".into(),
        tenant_id: "tenant-a".into(),
        repository_id: "repository-a".into(),
        proposed_node_id: "node-a".into(),
        public_key_fingerprint: "ed25519:7f3a".into(),
        nonce: vec![1; 32],
        signature: vec![2; 64],
    };

    let mut smuggled = proof.encode_to_vec();
    smuggled.push(0x52); // field 10, length-delimited — the enrolment key's tag
    smuggled.push(32);
    smuggled.extend(std::iter::repeat_n(0x2a, 32));

    assert_eq!(
        EnrollmentActivationProof::decode(smuggled.as_slice()).unwrap(),
        proof
    );
}

